// Sequential: N round trips — slow
async function fetchAllSequential(ids) {
  const out = [];
  for (const id of ids) {
    out.push(await fetch(`/api/items/${id}`).then((r) => r.json()));  // waits each time
  }
  return out;
}

// Parallel: one wait — correct default for independent work
async function fetchAllParallel(ids) {
  const promises = ids.map((id) => fetch(`/api/items/${id}`).then((r) => r.json()));
  return Promise.all(promises);        // preserves order
}

// Mixed: launch everything, then await with structured error handling
async function loadDashboard(userId) {
  const userPromise = fetchUser(userId);      // started NOW, not after stats
  const statsPromise = fetchStats(userId);    // overlaps user fetch
  const feedPromise = fetchFeed(userId).catch(() => [];  // feed is optional

  const [user, stats, feed] = await Promise.all([userPromise, statsPromise, feedPromise]);
  return { user, stats, feed };
}

// try/catch maps rejections to exceptions:
async function save(profile) {
  try {
    await api.save(profile);
  } catch (error) {
    // error is the rejection reason; UI can retry or show a message
    toast.error('Save failed');
    throw error;                 // rethrow if the caller must know
  }
}

